import math

state = {
    'mode': 'pull_forward',
    'pull_start_dist': None
}

def control(obs):
    look_deg = -23.0
    hitch = obs.get('hitch_deg', 0.0)
    progress = obs.get('progress', {})
    covered = progress.get('covered', 0.0)
    hold_s = obs.get('motion', {}).get('hold_s', 0.0)

    if hold_s > 0:
        return {'steer_deg': -20.0, 'speed_mps': 0.0, 'look_deg': look_deg}

    if state['mode'] == 'pull_forward':
        if state['pull_start_dist'] is None:
            state['pull_start_dist'] = covered
        if covered - state['pull_start_dist'] > -1.2:
            return {'steer_deg': -20.0, 'speed_mps': 1.0, 'look_deg': look_deg}
        else:
            state['mode'] = 'reverse'

    views = obs.get('views', {})
    cam = views.get('camera')
    bay = None
    if cam and cam.get('target_corners'):
        bay = cam['target_corners']

    target_hitch = 0.0
    if cam and 'walls' in cam and cam['walls']:
        th_rad = math.radians(-hitch)
        cos_th = math.cos(th_rad)
        sin_th = math.sin(th_rad)
        ox, oy = cam['origin']

        left_dists = []
        right_dists = []
        for b_deg, d in cam['walls']:
            rad = math.radians(b_deg)
            px = ox + d * math.cos(rad)
            py = oy + d * math.sin(rad)
            dx = px - ox
            dy = py - oy
            lat = -dx * sin_th + dy * cos_th
            back = -dx * cos_th - dy * sin_th
            if 0.2 < back < 5.0:
                if lat > 0:
                    left_dists.append(lat)
                else:
                    right_dists.append(-lat)

        if left_dists and right_dists:
            min_l = min(left_dists)
            min_r = min(right_dists)
            lat_err = (min_l - min_r)
            target_hitch = max(-25.0, min(25.0, lat_err * 12.0))
        elif right_dists and min(right_dists) < 1.0:
            target_hitch = 15.0
        elif left_dists and min(left_dists) < 1.0:
            target_hitch = -15.0

    if bay:
        b_deg = bay[0][0]
        ang_diff = 180.0 - abs(b_deg)
        if b_deg > 0:
            target_hitch = max(target_hitch, ang_diff * 0.5)
        else:
            target_hitch = min(target_hitch, -ang_diff * 0.5)

    hitch_error = hitch - target_hitch
    target_steer = max(-33.0, min(33.0, hitch_error * 2.8))

    return {
        'steer_deg': target_steer,
        'speed_mps': -0.5,
        'look_deg': look_deg
    }

