            return {'steer_deg': 0.0, 'speed_mps': obs['speed']['default_fwd'], 'look_deg': target_gaze}
        else:
            phase = 'reverse'

    speed = -0.75

    barrier_pts = []
    for view_name, view in obs.get('views', {}).items():
        if not view:
            continue
        ox, oy = view['origin']
        for b_deg, d_m in view.get('walls', []):
            rad = math.radians(b_deg)
            px = ox + d_m * math.cos(rad)
            py = oy + d_m * math.sin(rad)
            barrier_pts.append((px, py))

    trx, try_pos = obs['rig']['trailer_rear']

    left_clearance = 4.0
    right_clearance = 4.0
    for px, py in barrier_pts:
        if trx - 3.5 <= px <= trx + 1.5:
            d_y = py - try_pos
            if d_y > 0:
                left_clearance = min(left_clearance, d_y)
