import math

state = {
    'mode': 'RECOVER',
    'recover_timer': 2.0
}

def control(obs):
    t = obs['t']
    dt = obs.get('dt', 0.1)
    hitch = obs['hitch_deg']
    status = obs.get('status', '')
    hold = obs.get('motion', {}).get('hold_s', 0.0)

    # Target is at bearing +82 deg, ~7.5m away. Alley turns to the left!
    target = obs.get('target', {})
    in_sight = target.get('in_sight', False)
    t_bearing = target.get('bearing_deg', None)

    look_target = 130.0
    if in_sight and t_bearing is not None:
        look_target = max(-165.0, min(165.0, t_bearing))

    # If pinned or in penalty hold, wait or recover
    if status == 'PINNED' or hold > 0.5:
        state['mode'] = 'RECOVER'
        state['recover_timer'] = 2.0

    if state['mode'] == 'RECOVER':
        if hold > 0.0:
            return (0.0, 0.0, look_target)
        state['recover_timer'] -= dt
        if state['recover_timer'] <= 0:
            state['mode'] = 'REVERSE'
        else:
            # Pull forward slightly to clear rail contact
            # Trailer swung left (hitch +19), steer right (-steer) to pull straight
            return (-15.0, 0.5, look_target)

    # REVERSE MODE:
    desired_hitch = 0.0
    if in_sight and t_bearing is not None:
        if t_bearing >= 0:
            bearing_from_rear = 180.0 - t_bearing
        else:
            bearing_from_rear = -180.0 - t_bearing
        # Steer trailer smoothly towards target
        desired_hitch = max(-22.0, min(22.0, 0.5 * bearing_from_rear))

    # Closed loop hitch control: positive steer drives hitch down
    hitch_err = hitch - desired_hitch
    steer = 2.5 * hitch_err
    steer = max(-45.0, min(45.0, steer))

    v_rev = -0.35 if abs(desired_hitch) > 10.0 else -0.5
    return (steer, v_rev, look_target)

